SELECT t.id, t.dept_id, d.name deptName, t.post_code, t.post_category, t.post_name, t.post_sort, t.status, t.create_dept, t.create_by, t.create_time, t.update_by, t.update_time, t.remark FROM sys_post t left join sys_dept d on t.dept_id = d.id
AND post_name LIKE CONCAT('%', #{queryParams.postName}, '%')
AND dept_id = #{queryParams.deptId}
